INSERT INTO Recipes (recipe_id, name, serving_size, mins) VALUES (3, "Buffalo-Spiced Crispy Chicken Breasts", 2, 30);
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (1, 3, "• Adjust rack to top position (top and middle positions for 4 servings) and preheat oven to 425 degrees. Wash and dry all produce. • Cut broccoli florets into bite-size pieces if necessary. Trim and thinly slice scallions, separating whites from greens. • In a small bowl, combine half the sour cream, ½ tsp Frank’s Seasoning (1 tsp for 4), and a big pinch of salt. (You’ll use the rest of the sour cream and seasoning later.) Stir in water 1 tsp at a time until mixture reaches a drizzling consistency.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (2, 3, "Place 1 TBSP butter (2 TBSP for 4 servings) in a medium microwave safe bowl; microwave until melted, 30-45 seconds. Stir in panko, Monterey Jack, remaining Frank’s Seasoning, and a big pinch of salt and pepper.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (3, 3, "Dice potatoes into ½-inch pieces. • Place in a medium pot with enough salted water to cover by 2 inches. Bring to a boil and cook until tender, 15-20 minutes. • Reserve ½ cup potato cooking liquid, then drain and return empty pot to low heat. Add a drizzle of oil and scallion whites; cook until softened, 1-2 minutes. • Return potatoes to pot. Mash with 1 TBSP butter (2 TBSP for 4 servings) and remaining sour cream until smooth and creamy, adding splashes of reserved potato cooking liquid as needed. Season with salt and pepper. Remove from heat; keep covered until ready to serve.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (4, 3, "While potatoes cook, pat chicken* dry with paper towels and season all over with salt and pepper. • Place on one side of a lightly oiled baking sheet. (For 4 servings, spread chicken out across entire sheet.) Mound tops of chicken breasts with panko mixture, pressing firmly to adhere (no need to coat the undersides).");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (5, 3, "Toss broccoli on opposite side of sheet from chicken with a large drizzle of olive oil and a pinch of salt and pepper. (For 4 servings, add broccoli to a second baking sheet; roast chicken on top rack and broccoli on middle rack.) • Roast on top rack until chicken is golden brown and cooked through and broccoli is slightly crispy, 18-22 minutes. TIP: If broccoli is done before chicken, remove from sheet and continue roasting chicken.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (6, 3, "Transfer roasted broccoli to a large bowl; toss with 1 TBSP butter. • Divide potatoes, chicken, and broccoli between plates. Drizzle chicken with creamy Buffalo sauce and honey (or serve both on the side for dipping). Sprinkle potatoes and chicken with scallion greens and serve.");
INSERT INTO Ingredients_in_Recipe (ingredient_id, recipe_id, quantity, unit) VALUES (19, 3, 12, "ounce");
