INSERT INTO Recipes (recipe_id, name, serving_size, mins) VALUES (4, "W14 MOD Steakhouse-Style Pork Chops", 2, 35);
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (1, 4, "Adjust rack to top position (top and middle positions for 4 servings) and preheat oven to 425 degrees. Wash and dry produce. • Dice potatoes into ½-inch pieces. Cut broccoli florets into bite-size pieces if necessary. Halve, peel, and mince half the onion (whole onion for 4). Zest and quarter lemon. Trim and discard woody bottom ends from asparagus; cut crosswise into 1-inch pieces. (Save potatoes for another use.)");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (2, 4, "Toss potatoes on one side of a baking sheet with a drizzle of oil, salt, and pepper. (For 4 servings, spread potatoes out across entire sheet; roast on top rack for 20-25 minutes total.) • Roast on top rack for 5 minutes (you’ll add the broccoli then).");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (3, 4, "Once potatoes have roasted 5 minutes, remove sheet from oven. Carefully toss broccoli on empty side with a drizzle of oil, salt, and pepper. (For 4 servings, leave potatoes roasting and add broccoli to a second baking sheet; roast on middle rack.) • Return to top rack until potatoes are golden brown and broccoli is tender, 15-20 minutes more. Toss asparagus on opposite side of baking sheet from broccoli with a drizzle of oil, salt, and pepper. Roast on top rack until veggies are tender, 15-20 minutes. TIP: If asparagus is done before broccoli, remove from sheet and continue roasting broccoli.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (4, 4, "While veggies roast, pat pork* dry with paper towels; season all over with salt, then coat with as much Steak Spice as will stick. • Heat a drizzle of olive oil in a large pan over medium-high heat. Add pork and cook until browned and cooked through, 4-6 minutes per side. TIP: If crust begins to brown too quickly, reduce heat to medium. • Turn off heat; transfer pork to a cutting board. Wipe out pan.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (5, 4, "Heat a drizzle of olive oil in same pan over medium heat. Add minced onion; cook, stirring, until softened and lightly browned, 3-4 minutes. • Stir in stock concentrate and ¼ cup water (1⁄3 cup for 4 servings). Bring to a simmer and cook until slightly reduced, 2-3 minutes. • Remove from heat and stir in sour cream until combined. Season generously with pepper.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (6, 4, "Toss broccoli with lemon zest. • Thinly slice pork crosswise. • Divide pork, potatoes, and broccoli between plates. Spoon pan sauce over pork. Serve with lemon wedges on the side. Pork is fully cooked when internal temperature reaches 145°.");
