INSERT INTO Recipes (recipe_id, name, serving_size, mins) VALUES (5, "Pork Chops & Pineapple Mojo Sauce", 2, 30);
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (1, 5, "Wash and dry produce. Drain pineapple over a small bowl; reserve juice. Trim and dice cucumber into ¼-inch pieces. Halve and peel onion. Dice one-quarter of the onion (half the onion for 4 servings) into ¼-inch pieces; thinly slice another one-quarter of the onion (remaining onion for 4). Roughly chop cilantro. Quarter lime.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (2, 5, "In a small pot, combine rice, 1¼ cups water (2¼ cups for 4 servings), and a pinch of salt. Bring to a boil, then cover and reduce to a low simmer. Cook until rice is tender, 15-20 minutes. Keep covered off heat until ready to serve.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (3, 5, "While rice cooks, in a medium bowl, combine drained pineapple, cucumber, diced onion, half the cilantro, half the garlic powder (you'll use the rest later), 1 TBSP olive oil, ½ tsp sugar, and juice from half the lime (2 TBSP olive oil and 1 tsp sugar for 4 servings). Season with salt and pepper. Refrigerate until ready to serve.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (4, 5, "Pat pork* dry with paper towels and season all over with half the Cuban Spice Blend (you'll use the rest later), salt, and pepper. Heat a large drizzle of oil in a large pan over medium-high heat. Add pork and cook until browned and cooked through, 4-6 minutes per side. TIP: Reduce heat if pork is browning too quickly. Turn off heat; transfer to a cutting board to rest. Wipe out pan.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (5, 5, "Heat a drizzle of oil in pan used for pork over medium-high heat. Add sliced onion and cook, stirring occasionally, until softened, 2-4 minutes. Add pineapple juice, remaining Cuban Spice Blend, remaining garlic powder, and 1 tsp sugar (2 tsp for 4 servings); cook, stirring, until liquid has reduced, 1-2 minutes. Add ¼ cup water (½ cup for 4); cook, stirring, until sauce has thickened, 1-2 minutes. Remove from heat; stir in 2 TBSP butter (4 TBSP for 4) until melted. Add juice from one lime wedge (two wedges for 4). Taste and season with salt and pepper. TIP: If needed, add more water a splash at a time until saucy.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (6, 5, "Slice pork crosswise. Fluff rice with a fork; stir in remaining cilantro. Divide rice, pork, and salad between shallow bowls. Drizzle pork and rice with mojo sauce. Serve.");
INSERT INTO Ingredients_in_Recipe (ingredient_id, recipe_id, quantity, unit) VALUES (15, 5, 0.5, "unit");
