INSERT INTO Recipes (recipe_id, name, serving_size, mins) VALUES(10, "Sweet Corn & Poblano Chowder", 2, 40);
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (1, 10, "Adjust rack to top position and preheat oven to 425 degrees. Place 2 TBSP butter (4 TBSP for 4 servings) in a small microwave-safe bowl; set aside to soften (you’ll use it in step 4). Wash and dry produce. • Core, deseed, and dice poblano into ¼-inch pieces. Halve, peel, and finely dice half the shallot (all for 4). Dice potatoes into ½-inch pieces. Drain and rinse corn.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (2, 10, "Melt 2 TBSP plain butter (4 TBSP for 4 servings) in a medium pot over medium-high heat. Add poblano and diced shallot; season with salt and pepper. Cook, stirring, until softened, 2-3 minutes. • Add flour; cook, stirring, until lightly browned, 1 minute.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (3, 10, "Slowly stir milk into pot a splash at a time until fully incorporated. • Stir in 1½ cups water (2½ cups for 4 servings). • Add potatoes, stock concentrates, and half the Old Bay Seasoning (you’ll use more in the next step). Bring to a boil and cook, stirring occasionally, until potatoes are very tender, 15-20 minutes. TIP: To test, pierce one piece with a fork— it should go through easily.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (4, 10, "Meanwhile, combine softened butter, ¼ tsp Old Bay Seasoning, and ¼ tsp sugar until smooth. (For 4 servings, use ½ tsp Old Bay and ½ tsp sugar.) (TIP: If the butter is still cold, microwave for 10 seconds to soften.) Taste and add more Old Bay Seasoning if desired. • Halve baguette lengthwise; spread cut sides with Old Bay butter. Place, cut sides up, on a baking sheet. • Toast on top rack until golden, 3-5 minutes.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (5, 10, "Once potatoes are tender, reduce heat to low and mash with a potato masher or fork to desired consistency. TIP: We recommend mashing until almost smooth, leaving a few small potato pieces for texture. • Stir in cream cheese, corn, and Monterey Jack until fully incorporated and chowder is thick and creamy. If needed, stir in splashes of water until chowder reaches desired consistency (it will be very thick at this point). Season generously with salt and pepper.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (6, 10, "Halve Old Bay toast on a diagonal if desired. • Divide chowder between bowls. Garnish with sour cream. Serve with Old Bay toast on the side.");
INSERT INTO Ingredients_in_Recipe (ingredient_id, recipe_id, quantity, unit) VALUES (63, 10, 4, "teaspoon");
INSERT INTO Ingredients_in_Recipe (ingredient_id, recipe_id, quantity, unit) VALUES (3, 10, 2, "tablespoon");
