INSERT INTO Recipes (recipe_id, name, serving_size, mins) VALUES(12, "One-Pan Santa Fe Pork Tacos", 2, 20);
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (1, 12, "Wash and dry produce. • Halve, peel, and finely dice onion. Finely chop cilantro. Quarter lemon.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (2, 12, "Heat a drizzle of oil in a large pan over medium-high heat. Add onion and a pinch of salt; cook, stirring occasionally, until slightly softened and lightly browned, 2-3 minutes. • Add pork* and Southwest Spice. Cook, breaking up meat into pieces, until browned and cooked through, 4-6 minutes. TIP: If there’s excess grease in your pan, carefully pour it out.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (3, 12, "While pork cooks, in a large bowl, combine cabbage, mayonnaise, half the cilantro, juice from half the lemon (whole lemon for 4 servings), 1 tsp sugar (2 tsp for 4), and a pinch of salt and pepper.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (4, 12, "Stir Tex-Mex paste into pan with pork mixture until fully coated. Taste and season with salt and pepper. Remove pan from heat. • Wrap tortillas in damp paper towels and microwave until warm and pliable, 30 seconds. • Divide tortillas between plates and fill with pork filling, Monterey Jack, slaw, sour cream, and remaining cilantro. Serve with any remaining lemon wedges on the side.");
INSERT INTO Ingredients_in_Recipe (ingredient_id, recipe_id, quantity, unit) VALUES (29, 12, 1, "unit");
