INSERT INTO Recipes (recipe_id, name, serving_size, mins) VALUES(13, "Pecan-Crusted Chicken with Honey Mustard Sauce & Lemony Apple Salad", 2, 30);
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (1, 13, "Adjust rack to middle position and preheat oven to 450 degrees. Wash and dry produce. • Finely chop pecans (or crush in their bag with a heavy pan or rolling pin).");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (2, 13, "Place 1 TBSP butter (2 TBSP for 4 servings) in a medium microwave-safe bowl. Microwave until melted, 30 seconds. • Let cool slightly, then stir in chopped pecans, panko, half the Fry Seasoning (you’ll use the rest later), a drizzle of olive oil, and a pinch of salt and pepper.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (3, 13, "In a small bowl, combine honey, mustard, and mayonnaise.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (4, 13, "Pat chicken* dry with paper towels; season with remaining Fry Seasoning, salt, and pepper. Place on a lightly oiled baking sheet. • Evenly spread tops of chicken with a thin layer of honey mustard sauce (save the rest for serving). Mound with pecan mixture, pressing firmly to adhere (no need to coat the undersides). • Roast on middle rack until crust is golden brown and chicken is cooked through, 15-20 minutes.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (5, 13, "Meanwhile, halve, core, and thinly slice apple. Quarter lemon. • In a large bowl, toss mixed greens and apple with a large drizzle of olive oil and as much lemon juice as you like. Season with salt and pepper.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (6, 13, "Divide chicken and salad between plates. Drizzle chicken with remaining honey mustard sauce. Serve with any remaining lemon wedges on the side.");
INSERT INTO Ingredients_in_Recipe (ingredient_id, recipe_id, quantity, unit) VALUES (78, 13, 0.5, "ounce");
