INSERT INTO Recipes (recipe_id, name, serving_size, mins) VALUES(17, "Thai Coconut Curry Chicken", 2, 30);
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (1, 17, "In a small pot, combine rice, ¾ cup water (1½ cups for 4 servings), and a pinch of salt. Bring to a boil, then cover and reduce to a low simmer. Cook until rice is tender, 15-18 minutes. • Keep covered off heat until ready to serve.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (2, 17, "While rice cooks, wash and dry all produce. • Core, deseed, and dice bell pepper into 1-inch pieces. Zest and quarter lime. Mince cilantro. Thinly slice chili. • Pat chicken* dry with paper towels.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (3, 17, "Heat a large drizzle of oil in a medium pan over medium-high heat (use a large pan for 4 servings). Add bell pepper and a big pinch of salt. Cook, stirring occasionally, 5 minutes.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (4, 17, "Add chicken, another large drizzle of oil, and a big pinch of salt to pan with bell pepper. Cook, stirring occasionally, until chicken is lightly browned, 3-4 minutes (it’ll finish cooking in the next step). • Stir in half the curry powder (all for 4 servings); cook for 1 minute.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (5, 17, "Thoroughly shake coconut milk in container before opening • Stir ⅔ cup coconut milk (1⅓ cups for 4 servings), chili sauce, stock concentrate, juice from half the lime, and 1 tsp sugar (2 tsp for 4) into pan with chicken mixture. Bring to a simmer, then reduce heat to medium low. Simmer until sauce is thickened, bell pepper is tender, and chicken is cooked through, 4-6 minutes. • Taste and season with salt and more lime juice if desired. Turn off heat.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (6, 17, "Fluff rice with a fork; stir in lime zest, half the cilantro, and 1 TBSP butter (2 TBSP for 4 servings). Season with salt and pepper. • Divide rice between shallow bowls and top with coconut curry chicken, remaining cilantro, and a pinch of chili if desired. Serve with any remaining lime wedges on the side.");
INSERT INTO Ingredients_in_Recipe (ingredient_id, recipe_id, quantity, unit) VALUES (48, 17, 0.5, "cup");
INSERT INTO Ingredients_in_Recipe (ingredient_id, recipe_id, quantity, unit) VALUES (35, 17, 1, "unit");
