INSERT INTO Recipes (recipe_id, name, serving_size, mins) VALUES(18, "Sesame Soy Beef Bowls", 2, 20);
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (1, 18, "Wash and dry produce. • In a small pot, combine rice, 1¼ cups water (2¼ cups for 4 servings), and a pinch of salt. Bring to a boil, then cover and reduce to a low simmer. Cook until rice is tender, 15-18 minutes. Keep covered off heat until ready to serve. • Meanwhile, trim and thinly slice scallions, separating whites from greens. • In a small bowl, combine mayonnaise with sriracha to taste. Stir in water 1 tsp at a time until mixture reaches a drizzling consistency. Season with salt and pepper.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (2, 18, "Heat half the sesame oil (you’ll use the rest in the next step) in a large pan over medium-high heat. Add carrots and scallion whites; cook, stirring occasionally, until slightly softened, 1-2 minutes. Season with salt, pepper, and a pinch of sugar. • Transfer to a second small bowl and cover to keep warm.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (3, 18, "Heat a drizzle of oil in pan used for carrots over medium high heat. Add beef* and cook, breaking up meat into pieces, until browned, 3-5 minutes. TIP: If there’s excess grease in your pan, carefully pour it out. • Stir in sweet soy glaze, half the vinegar (all for 4 servings), and remaining sesame oil. Bring to a simmer and cook until sauce has thickened and beef is cooked through, 2-3 minutes. • Remove from heat. Taste and season with salt and pepper if desired.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (4, 18, "Fluff rice with a fork and stir in 1 TBSP butter (2 TBSP for 4 servings); season with salt and pepper. • Divide rice between bowls; top with carrots and sesame soy beef. Drizzle with sriracha mayo and sprinkle with scallion greens. Serve.");
