INSERT INTO Recipes (recipe_id, name, serving_size, mins) VALUES(19, "Salsa Verde Enchiladas", 2, 35);
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (1, 19, "Adjust rack to top position and preheat oven to 475 degrees. Wash and dry all produce. Core, deseed, and dice poblano. Finely dice tomato. Trim and thinly slice scallions, separating whites from greens. Drain beans over a small bowl, reserving liquid. Thinly slice chili.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (2, 19, "Heat a drizzle of oil in a large pan over medium-high heat. Add poblano and cook until just softened, 3-4 minutes.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (3, 19, "Meanwhile, reserve ½ tsp Southwest Spice (1 tsp for 4 servings) in a second small bowl. Once poblano is just softened, add tomato, scallion whites, half the beans (you’ll use the rest later), 2 TBSP reserved bean liquid, and remaining Southwest Spice to pan. Cook, stirring, until fragrant and warmed through, 2-3 minutes. Season with salt and pepper.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (4, 19, "Heat a large drizzle of oil in a small pot over medium-high heat. Add remaining beans and cook, stirring, until slightly softened, 2-3 minutes. Add 3 TBSP reserved bean liquid (⅓ cup for 4 servings; you may have some left over). Simmer until warmed through, 1-2 minutes. Reduce heat to low and stir in 1 TBSP butter (2 TBSP for 4). Turn off heat; mash with a potato masher or fork until mostly smooth. Season with plenty of salt and pepper.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (5, 19, "Spread tortillas with mashed beans. Place a small amount of filling on one half of each tortilla. Roll up tortillas, starting with filled side, and place seam sides down in an 8-by-11-inch baking dish or ovenproof pan. (For 4 servings, place in a 9-by-13-inch baking dish or two smaller ones.) Spoon enough salsa over to generously coat (you may have some left over). Sprinkle with Monterey Jack. Bake on top rack until salsa is bubbly and cheese melts, 3-5 minutes.");
INSERT INTO Steps_in_Recipe (step_id, recipe_id, instruction) VALUES (6, 19, "Meanwhile, add sour cream to bowl with reserved Southwest Spice. Stir in warm water 1 tsp at a time until mixture reaches a drizzling consistency. Season with salt and pepper. Top baked enchiladas with crema, scallion greens, and as much chili as you like. Divide between plates and serve.");
INSERT INTO Ingredients_in_Recipe (ingredient_id, recipe_id, quantity, unit) VALUES (24, 19, 2, "unit");
